def dense_axis(k, v, h):
    n = len(k)
    a = np.zeros((n, n))
    for i in range(n):
        if i in (0, n - 1):
            j = 1 if i == 0 else n - 2
            a[i, j] = -k[i] / h ** 2
            a[i, i] = -a[i, j]
        else:
            a[i, i - 1] = -(k[i] + k[i - 1]) / (2 * h ** 2) - max(v[i], 0) / h
            a[i, i + 1] = -(k[i] + k[i + 1]) / (2 * h ** 2) - max(-v[i], 0) / h
            a[i, i] = (k[i - 1] + 2 * k[i] + k[i + 1]) / (2 * h ** 2) + abs(v[i]) / h
    return a

def pmap(q, model):
    q = np.asarray(q)
    if model == 'shared':
        return np.tile([q[0], q[1], 0], 4)
    if model == 'axes':
        return np.repeat(np.column_stack([q.reshape(2, 2), np.zeros(2)]), 2, axis=0).ravel()
    if model == 'walls':
        return np.column_stack([q.reshape(4, 2), np.zeros(4)]).ravel()
    return q
